-- ─── D5. Seats with no office yet: clone the city's council office onto the district ─────────────────
INSERT INTO essentials.offices (id, chamber_id, district_id, title, representing_state, representing_city, description, seats,
                                normalized_position_name, partisan_type, salary, is_appointed_position, is_vacant, vacant_since,
                                faces_retention_vote, role_canonical, voting_powers, representation_note)
SELECT v.oid, t.chamber_id, v.did, v.title, t.representing_state, t.representing_city, t.description, 1,
       v.title, t.partisan_type, t.salary, t.is_appointed_position, v.vac, NULL,
       t.faces_retention_vote, t.role_canonical, t.voting_powers, t.representation_note
  FROM (VALUES
    ('8ddc744b-96fe-409e-90d2-3a1ba7a7880b'::uuid, '67a8faf1-3505-4a08-824a-2186cd4e52ea'::uuid, 'Council Member (District 2)', true, '2fe47b4b-33e8-4e15-8e8c-9b1406617394'::uuid),
    ('ed2f54f6-0c0b-42f5-b6d4-b7b74f8b04c3'::uuid, 'd7772537-61b4-49ef-9c13-1090d010fa7c'::uuid, 'Council Member (District 4)', true, '2fe47b4b-33e8-4e15-8e8c-9b1406617394'::uuid),
    ('27c10c56-4c3e-4f7a-9729-86420209c676'::uuid, 'cec36ef9-36c3-4057-9b02-62e4fb045b37'::uuid, 'Council Member (District 5)', true, '2fe47b4b-33e8-4e15-8e8c-9b1406617394'::uuid)
  ) AS v(oid, did, title, vac, tpl)
  JOIN essentials.offices t ON t.id = v.tpl
