-- ─── W1. West Covina elected City Clerk + City Treasurer (Carson pattern). The city had no LOCAL_EXEC
--        whole-city district, so one is created (cloned from its whole-city LOCAL row). ───────────────
INSERT INTO essentials.districts (id, label, district_type, district_id, state, city, num_officials, mtfcc, geo_id,
                                  is_judicial, has_unknown_boundaries, retention, government_id, official_web_url, representation_basis, ocd_id)
SELECT 'd07a062f-c0c6-42a0-9c27-a4b5a3954f5a'::uuid, 'West Covina City Officers', 'LOCAL_EXEC', '0', p.state, p.city, 2, 'G4110', '0684200',
       false, false, false, p.government_id, p.official_web_url, 'residency', p.ocd_id
  FROM (SELECT * FROM essentials.districts x WHERE x.geo_id = '0684200' AND x.district_type = 'LOCAL' ORDER BY x.id LIMIT 1) p
 WHERE NOT EXISTS (SELECT 1 FROM essentials.districts d WHERE d.id = 'd07a062f-c0c6-42a0-9c27-a4b5a3954f5a'::uuid);
