-- ─── 0. Pre-flight: every binding target exists ───────────────────────────────────────
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM (VALUES
    ('bellflower-council-district-1', 'LOCAL', NULL, 'Bellflower City Council District 1'),
    ('0636546', 'LOCAL_EXEC', 'Mayor', 'Inglewood Mayor'),
    ('inglewood-council-district-1', 'LOCAL', NULL, 'Inglewood City Council District 1'),
    ('inglewood-council-district-2', 'LOCAL', NULL, 'Inglewood City Council District 2'),
    ('palmdale-council-district-3', 'LOCAL', NULL, 'Palmdale City Council District 3'),
    ('palmdale-council-district-4', 'LOCAL', NULL, 'Palmdale City Council District 4'),
    ('palmdale-council-district-5', 'LOCAL', NULL, 'Palmdale City Council District 5'),
    ('west-covina-council-district-2', 'LOCAL', NULL, 'West Covina City Council District 2'),
    ('west-covina-council-district-4', 'LOCAL', NULL, 'West Covina City Council District 4'),
    ('west-covina-council-district-5', 'LOCAL', NULL, 'West Covina City Council District 5'),
    ('0684200', 'LOCAL_EXEC', 'City Clerk', 'West Covina City Clerk'),
    ('0684200', 'LOCAL_EXEC', 'City Treasurer', 'West Covina City Treasurer'),
    ('santa-clarita-council-district-2', 'LOCAL', NULL, 'Santa Clarita City Council District 2'),
    ('santa-clarita-council-district-4', 'LOCAL', NULL, 'Santa Clarita City Council District 4'),
    ('santa-clarita-council-district-5', 'LOCAL', NULL, 'Santa Clarita City Council District 5')
  ) AS v(place, dtype, otitle, pos)
   WHERE NOT EXISTS (SELECT 1 FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                      WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle));
  IF n <> 0 THEN RAISE EXCEPTION 'pre-flight: % race(s) with no office to bind to', n; END IF;
END $$;

-- ─── 1. Races ─────────────────────────────────────────────────────────────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, t.office_id, t.pos, NULL, t.seats
  FROM (SELECT v.pos, v.seats,
               (SELECT o.id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                 WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle)
                 ORDER BY o.id LIMIT 1) AS office_id
          FROM (VALUES
    ('bellflower-council-district-1', 'LOCAL', NULL, 'Bellflower City Council District 1', 1),
    ('0636546', 'LOCAL_EXEC', 'Mayor', 'Inglewood Mayor', 1),
    ('inglewood-council-district-1', 'LOCAL', NULL, 'Inglewood City Council District 1', 1),
    ('inglewood-council-district-2', 'LOCAL', NULL, 'Inglewood City Council District 2', 1),
    ('palmdale-council-district-3', 'LOCAL', NULL, 'Palmdale City Council District 3', 1),
    ('palmdale-council-district-4', 'LOCAL', NULL, 'Palmdale City Council District 4', 1),
    ('palmdale-council-district-5', 'LOCAL', NULL, 'Palmdale City Council District 5', 1),
    ('west-covina-council-district-2', 'LOCAL', NULL, 'West Covina City Council District 2', 1),
    ('west-covina-council-district-4', 'LOCAL', NULL, 'West Covina City Council District 4', 1),
    ('west-covina-council-district-5', 'LOCAL', NULL, 'West Covina City Council District 5', 1),
    ('0684200', 'LOCAL_EXEC', 'City Clerk', 'West Covina City Clerk', 1),
    ('0684200', 'LOCAL_EXEC', 'City Treasurer', 'West Covina City Treasurer', 1),
    ('santa-clarita-council-district-2', 'LOCAL', NULL, 'Santa Clarita City Council District 2', 1),
    ('santa-clarita-council-district-4', 'LOCAL', NULL, 'Santa Clarita City Council District 4', 1),
    ('santa-clarita-council-district-5', 'LOCAL', NULL, 'Santa Clarita City Council District 5', 1)
          ) AS v(place, dtype, otitle, pos, seats)) t
 WHERE t.office_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = t.pos);

