    ('Santa Clarita City Council District 5', 'Bob Khalsa', 'Bob', 'Khalsa', NULL::uuid, false, NULL, 'City of Santa Clarita City Clerk, Memorandum: List of Qualified Candidates, General Municipal Election November 3, 2026, 8/13/2026 (santaclarita.gov/city-clerk/.../List-of-Qualified-Candidates-Memo.pdf). Retrieved 2026-09-23.'),
    ('Santa Clarita City Council District 5', 'Liliia Chernova', 'Liliia', 'Chernova', NULL::uuid, false, NULL, 'City of Santa Clarita City Clerk, Memorandum: List of Qualified Candidates, General Municipal Election November 3, 2026, 8/13/2026 (santaclarita.gov/city-clerk/.../List-of-Qualified-Candidates-Memo.pdf). Retrieved 2026-09-23.'),
    ('Santa Clarita City Council District 5', 'Kelvin Driscoll', 'Kelvin', 'Driscoll', NULL::uuid, false, NULL, 'City of Santa Clarita City Clerk, Memorandum: List of Qualified Candidates, General Municipal Election November 3, 2026, 8/13/2026 (santaclarita.gov/city-clerk/.../List-of-Qualified-Candidates-Memo.pdf). Retrieved 2026-09-23.')
  ) AS v(pos, full_name, first_name, last_name, pid, inc, desig, src)
  JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
 WHERE NOT EXISTS (SELECT 1 FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND lower(rc.full_name) = lower(v.full_name));

-- ─── 3. Antipartisan: clear the stored party on every linked candidate row ──────────
UPDATE essentials.politicians SET party = NULL
 WHERE party IS NOT NULL AND id IN ('123c9a42-5715-4ab2-a8bd-76e7adbca27b', '1bb5c062-9b9d-44de-820b-c3efe0d08222', '2872d7a4-612b-4d9d-9531-699e3c344002', '362f1ec5-20aa-4e7a-a00d-7f626ae70138', '625a53c8-209f-4231-bbc0-05edbd1c0591', '6854ec39-d6e2-44c4-8c60-0d809234f935', '7a04bf87-ab95-4ae7-a142-9899662637b1', 'd18dcb81-ad41-468f-9b12-a70ed21fd3a7', 'e024113e-ab16-4af6-aa75-d6ce89690a19', 'e4fd3203-bf10-4900-91f0-bf6eb58622a0', 'ecc57cd4-aebc-49b7-b324-e28a0aaf05df', 'f5775ca1-99f4-4cc2-acf2-5afaacdd94b3');

-- ─── 4. Post-verify gate ──────────────────────────────────────────────────────────────
DO $$
DECLARE
  pos text[] := ARRAY['Bellflower City Council District 1', 'Inglewood Mayor', 'Inglewood City Council District 1', 'Inglewood City Council District 2', 'Palmdale City Council District 3', 'Palmdale City Council District 4', 'Palmdale City Council District 5', 'West Covina City Council District 2', 'West Covina City Council District 4', 'West Covina City Council District 5', 'West Covina City Clerk', 'West Covina City Treasurer', 'Santa Clarita City Council District 2', 'Santa Clarita City Council District 4', 'Santa Clarita City Council District 5'];
  n_races int; n_cands int; n_null int; n_party int; n_badcount int; n_inc int; n_badinc int; n_extralink int; n_linked int; n_incseat int;
  n_overinc int; n_unreach int; n_pparty int; n_dpoly int; n_seatok int; n_dbad int; n_size int; n_dleak int; n_wc int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL), count(*) FILTER (WHERE r.primary_party IS NOT NULL)
    INTO n_races, n_null, n_party FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_cands FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  -- each race carries exactly the clerk's field, on the expected seat count
  SELECT count(*) INTO n_badcount FROM (VALUES
      ('Bellflower City Council District 1', 1, 2, 1),
      ('Inglewood Mayor', 1, 6, 1),
      ('Inglewood City Council District 1', 1, 4, 0),
      ('Inglewood City Council District 2', 1, 2, 1),
      ('Palmdale City Council District 3', 1, 5, 1),
      ('Palmdale City Council District 4', 1, 4, 1),
      ('Palmdale City Council District 5', 1, 3, 0),
      ('West Covina City Council District 2', 1, 3, 1),
      ('West Covina City Council District 4', 1, 3, 1),
      ('West Covina City Council District 5', 1, 2, 1),
      ('West Covina City Clerk', 1, 1, 1),
      ('West Covina City Treasurer', 1, 1, 1),
      ('Santa Clarita City Council District 2', 1, 3, 0),
      ('Santa Clarita City Council District 4', 1, 5, 0),
      ('Santa Clarita City Council District 5', 1, 3, 0)
    ) AS v(pos, seats, n_cand, n_inc)
    LEFT JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
   WHERE r.id IS NULL OR r.seats <> v.seats
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id) <> v.n_cand
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) <> v.n_inc;
  -- incumbents: linked, and holding THIS race's own seat (for a district race: that district's office)
  -- any linked candidate (incl. a sitting official running for another seat): a current holder somewhere in the city
  SELECT count(*) FILTER (WHERE rc.is_incumbent),
         count(*) FILTER (WHERE rc.is_incumbent AND rc.politician_id IS NULL),
         count(*) FILTER (WHERE rc.politician_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
             JOIN essentials.districts d2 ON d2.id = o2.district_id
            WHERE och.politician_id = rc.politician_id
              AND (d2.geo_id = cm.place OR (cm.pat <> '' AND d2.geo_id LIKE cm.pat)
                   OR d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)))),
         count(*) FILTER (WHERE rc.politician_id IS NOT NULL),
         count(*) FILTER (WHERE rc.is_incumbent AND rc.politician_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
             JOIN essentials.districts d2 ON d2.id = o2.district_id
            WHERE och.politician_id = rc.politician_id
              AND d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)))
    INTO n_inc, n_badinc, n_extralink, n_linked, n_incseat
    FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN (VALUES
      ('Bellflower City Council District 1', '0604982', 'bellflower-council-district-%'),
      ('Inglewood Mayor', '0636546', 'inglewood-council-district-%'),
      ('Inglewood City Council District 1', '0636546', 'inglewood-council-district-%'),
      ('Inglewood City Council District 2', '0636546', 'inglewood-council-district-%'),
      ('Palmdale City Council District 3', '0655156', 'palmdale-council-district-%'),
      ('Palmdale City Council District 4', '0655156', 'palmdale-council-district-%'),
      ('Palmdale City Council District 5', '0655156', 'palmdale-council-district-%'),
      ('West Covina City Council District 2', '0684200', 'west-covina-council-district-%'),
      ('West Covina City Council District 4', '0684200', 'west-covina-council-district-%'),
      ('West Covina City Council District 5', '0684200', 'west-covina-council-district-%'),
      ('West Covina City Clerk', '0684200', 'west-covina-council-district-%'),
      ('West Covina City Treasurer', '0684200', 'west-covina-council-district-%'),
      ('Santa Clarita City Council District 2', '0669088', 'santa-clarita-council-district-%'),
      ('Santa Clarita City Council District 4', '0669088', 'santa-clarita-council-district-%'),
      ('Santa Clarita City Council District 5', '0669088', 'santa-clarita-council-district-%')
    ) AS cm(cpos, place, pat) ON cm.cpos = r.position_name
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_overinc FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) > r.seats;
  -- END TO END: an interior point of each race's own polygon reaches that race
  SELECT count(*) INTO n_unreach FROM essentials.races r
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.geofence_boundaries me ON me.geo_id = d.geo_id AND me.mtfcc = d.mtfcc
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb
                      WHERE gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
                        AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(me.geometry)));
  SELECT count(*) INTO n_pparty FROM essentials.politicians p WHERE p.party IS NOT NULL AND p.id IN (
    SELECT rc.politician_id FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
     WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND rc.politician_id IS NOT NULL);
  IF n_races <> 15 THEN RAISE EXCEPTION 'expected 15 races, got %', n_races; END IF;
  IF n_cands <> 47 THEN RAISE EXCEPTION 'expected 47 candidates, got %', n_cands; END IF;
  IF n_null <> 0 OR n_party <> 0 THEN RAISE EXCEPTION 'office-less (%) or partisan (%) race', n_null, n_party; END IF;
  IF n_badcount <> 0 THEN RAISE EXCEPTION '% race(s) whose seats / candidates / incumbents differ from the clerk list', n_badcount; END IF;
  IF n_inc <> 10 THEN RAISE EXCEPTION 'expected 10 incumbents, got %', n_inc; END IF;
  IF n_badinc <> 0 THEN RAISE EXCEPTION '% incumbent(s) left unlinked', n_badinc; END IF;
  IF n_extralink <> 0 THEN RAISE EXCEPTION '% linked candidate(s) are not a current holder in their city', n_extralink; END IF;
  IF n_linked <> 12 THEN RAISE EXCEPTION 'expected 12 linked candidates, got %', n_linked; END IF;
  IF n_incseat <> 0 THEN RAISE EXCEPTION '% incumbent(s) do not hold the seat their race is for', n_incseat; END IF;
  IF n_overinc <> 0 THEN RAISE EXCEPTION '% race(s) with more incumbents than seats', n_overinc; END IF;
  IF n_unreach <> 0 THEN RAISE EXCEPTION '% race(s) not reached from inside their own city', n_unreach; END IF;
  IF n_pparty <> 0 THEN RAISE EXCEPTION '% linked candidate row(s) still carry a party', n_pparty; END IF;
  -- every new district row resolves to its polygon
  SELECT count(*) INTO n_dpoly FROM essentials.districts d JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND gb.mtfcc = d.mtfcc
   WHERE d.district_type = 'LOCAL' AND d.id IN ('915d0d93-5f48-4660-a374-ee4b3599742e', 'e571c85c-6101-4827-9086-469e880da192', 'ee9f4621-81e9-4160-8c8d-f672d3c27f75', 'c2a47fa2-401f-40d6-8be7-58ceb4db8db2', 'e13d8d0b-6d0e-41b8-a004-24d4c43ea9a5', '53dde03b-11a0-4132-845b-a78f903b6769', 'd8e7ff8f-07dc-45a9-9d63-71e1b2a44b78', '3a0ef57b-7ee3-492d-a522-97dd8437c4a7', '016836b2-7e74-4911-bdfb-a99420dc116f', '4d09b850-da3a-4b3b-9318-f37d914cc77c', 'df993e18-b2d5-4464-aa80-cc7ddb94d09e', 'b173e934-0f2a-4432-8236-d3442b71a141', '40b831ee-8430-4ff8-8e4c-322f45bc1ea7', 'e3cd19c9-e390-49a2-b0fa-0ef69871b489', 'c17474d7-aa0e-4146-9fe8-64093171023e', '87e750e3-5c36-42ec-b790-5c8c2823dc82', 'c633b1eb-500c-4b9e-b44e-dbcced05c088', '19488d05-9a11-490b-a35d-30452b238273', '5684112d-c01c-4adf-a1f3-2547e75097f5', '0daacf24-04c7-4177-8ca7-4e1d43d0a0a0', '67a8faf1-3505-4a08-824a-2186cd4e52ea', 'e4f6bd43-048a-43bd-b337-a6d382ed5eee', 'd7772537-61b4-49ef-9c13-1090d010fa7c', 'cec36ef9-36c3-4057-9b02-62e4fb045b37');
  -- every seat sits where it should, with its title, held by the named member (or flagged vacant)
  SELECT count(*) INTO n_seatok FROM (VALUES
      ('7408185f-600c-4b02-8949-431347f21390'::uuid, 'd18dcb81-ad41-468f-9b12-a70ed21fd3a7'::uuid, 'bellflower-council-district-1', 'Council Member (District 1)'),
      ('3935cd4b-727b-41fb-96c3-87f66b0c385c'::uuid, 'dd2c2cfd-401f-4b35-916f-caba8ca9b722'::uuid, 'bellflower-council-district-2', 'Council Member (District 2)'),
      ('c8314557-454e-4202-b2cb-00f23b636308'::uuid, 'a4ff4532-57d7-49e1-8eea-9313ce347d53'::uuid, 'bellflower-council-district-3', 'Council Member (District 3)'),
      ('581c5602-b72c-49f6-8b6e-c3e653eefbce'::uuid, '4384a5d8-68b2-4e24-81e2-5208f5c61a34'::uuid, 'bellflower-council-district-4', 'Council Member (District 4)'),
      ('bdd2040f-8f8d-4543-b017-3caad9be4510'::uuid, '31c35458-6cc0-43ad-b431-841846e81875'::uuid, 'bellflower-council-district-5', 'Council Member (District 5)'),
      ('8e9b0c61-0379-4a50-943d-951fdd8e632f'::uuid, '7a04bf87-ab95-4ae7-a142-9899662637b1'::uuid, 'inglewood-council-district-1', 'Council Member (District 1)'),
      ('41aa3576-b878-4206-a218-47c412ad8e2b'::uuid, '123c9a42-5715-4ab2-a8bd-76e7adbca27b'::uuid, 'inglewood-council-district-2', 'Council Member (District 2)'),
      ('ddcd280b-565d-496c-9ec4-0e43abb7b580'::uuid, '6ed19c10-7b34-47f0-8705-0d154271e362'::uuid, 'inglewood-council-district-3', 'Council Member (District 3)'),
      ('35b92278-1f5f-4f1a-91f9-e1b642f580cf'::uuid, '729bc539-3175-4e5d-96ba-c18768890e1e'::uuid, 'inglewood-council-district-4', 'Council Member (District 4)'),
      ('198661de-2850-46a1-954e-ef502122a40c'::uuid, '475b846d-bce8-43e0-bac8-bd65d58d9c46'::uuid, 'palmdale-council-district-1', 'Council Member (District 1)'),
      ('2e584cbd-f6e9-4213-8a7d-0ed319ad6c55'::uuid, '6e5d3005-07e5-4c57-a3e0-033a2b17bbdc'::uuid, 'palmdale-council-district-2', 'Council Member (District 2)'),
      ('5ca39492-9c7e-47e1-b8be-af7741677576'::uuid, '362f1ec5-20aa-4e7a-a00d-7f626ae70138'::uuid, 'palmdale-council-district-3', 'Council Member (District 3)'),
      ('a67a975e-9743-435b-a44c-1badb47866c3'::uuid, 'e024113e-ab16-4af6-aa75-d6ce89690a19'::uuid, 'palmdale-council-district-4', 'Council Member (District 4)'),
      ('6ca2f775-a206-42f4-817e-bfb8d0f865aa'::uuid, '579fb5f2-2313-4423-a412-b4ae101c6e8e'::uuid, 'palmdale-council-district-5', 'Council Member (District 5)'),
      ('0f3cce5f-9509-4268-a3fe-2ce972ead493'::uuid, '22fc2cdc-2f51-4d81-8814-4b54b2bc6582'::uuid, 'west-covina-council-district-1', 'Council Member (District 1)'),
      ('4a8f2fd6-755b-448c-8824-bb42ad170a33'::uuid, '2872d7a4-612b-4d9d-9531-699e3c344002'::uuid, 'west-covina-council-district-2', 'Council Member (District 2)'),
      ('abd27abb-42c6-4734-b683-5fac4d978174'::uuid, 'f5bf4ec4-7d1b-460e-b4e2-539826c59596'::uuid, 'west-covina-council-district-3', 'Council Member (District 3)'),
      ('50471af9-bc27-4c68-aff4-49a97c313a1e'::uuid, 'ecc57cd4-aebc-49b7-b324-e28a0aaf05df'::uuid, 'west-covina-council-district-4', 'Council Member (District 4)'),
      ('65bf4e71-cd21-4394-802d-8630bcd9f48e'::uuid, '1bb5c062-9b9d-44de-820b-c3efe0d08222'::uuid, 'west-covina-council-district-5', 'Council Member (District 5)'),
      ('2fe47b4b-33e8-4e15-8e8c-9b1406617394'::uuid, '3dab8dca-2ce0-403b-8f4f-d6137e11731d'::uuid, 'santa-clarita-council-district-1', 'Council Member (District 1)'),
      ('aa2ac2d7-60bb-4320-a17c-064635eeba56'::uuid, '434cd9b0-ce80-42fd-b71d-f221349e33f5'::uuid, 'santa-clarita-council-district-3', 'Council Member (District 3)'),
      ('d3c1fddc-f99c-49e9-ae6e-dc09dfb300b7'::uuid, '6854ec39-d6e2-44c4-8c60-0d809234f935'::uuid, NULL, 'Council Member (At-Large)'),
      ('d62b5922-5125-4e36-b129-07d28945f1c6'::uuid, '9476ec1c-9e60-4dae-b398-c81c63f6f670'::uuid, NULL, 'Council Member (At-Large)'),
      ('20fdfc6e-40c7-4277-846e-51341726d079'::uuid, '069fc0f2-d1eb-4fac-828a-3d9030d4f2a9'::uuid, NULL, 'Council Member (At-Large)'),
      ('8ddc744b-96fe-409e-90d2-3a1ba7a7880b'::uuid, NULL::uuid, 'santa-clarita-council-district-2', 'Council Member (District 2)'),
      ('ed2f54f6-0c0b-42f5-b6d4-b7b74f8b04c3'::uuid, NULL::uuid, 'santa-clarita-council-district-4', 'Council Member (District 4)'),
      ('27c10c56-4c3e-4f7a-9729-86420209c676'::uuid, NULL::uuid, 'santa-clarita-council-district-5', 'Council Member (District 5)')
    ) AS v(oid, pid, dgeo, title)
    JOIN essentials.offices o ON o.id = v.oid AND o.title = v.title
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE (v.dgeo IS NULL OR d.geo_id = v.dgeo)
     AND ((v.pid IS NOT NULL AND och.politician_id = v.pid) OR (v.pid IS NULL AND och.politician_id IS NULL AND o.is_vacant));
  -- each district row carries exactly one office
  SELECT count(*) INTO n_dbad FROM essentials.districts d WHERE d.id IN ('915d0d93-5f48-4660-a374-ee4b3599742e', 'e571c85c-6101-4827-9086-469e880da192', 'ee9f4621-81e9-4160-8c8d-f672d3c27f75', 'c2a47fa2-401f-40d6-8be7-58ceb4db8db2', 'e13d8d0b-6d0e-41b8-a004-24d4c43ea9a5', '53dde03b-11a0-4132-845b-a78f903b6769', 'd8e7ff8f-07dc-45a9-9d63-71e1b2a44b78', '3a0ef57b-7ee3-492d-a522-97dd8437c4a7', '016836b2-7e74-4911-bdfb-a99420dc116f', '4d09b850-da3a-4b3b-9318-f37d914cc77c', 'df993e18-b2d5-4464-aa80-cc7ddb94d09e', 'b173e934-0f2a-4432-8236-d3442b71a141', '40b831ee-8430-4ff8-8e4c-322f45bc1ea7', 'e3cd19c9-e390-49a2-b0fa-0ef69871b489', 'c17474d7-aa0e-4146-9fe8-64093171023e', '87e750e3-5c36-42ec-b790-5c8c2823dc82', 'c633b1eb-500c-4b9e-b44e-dbcced05c088', '19488d05-9a11-490b-a35d-30452b238273', '5684112d-c01c-4adf-a1f3-2547e75097f5', '0daacf24-04c7-4177-8ca7-4e1d43d0a0a0', '67a8faf1-3505-4a08-824a-2186cd4e52ea', 'e4f6bd43-048a-43bd-b337-a6d382ed5eee', 'd7772537-61b4-49ef-9c13-1090d010fa7c', 'cec36ef9-36c3-4057-9b02-62e4fb045b37')
     AND (SELECT count(*) FROM essentials.offices o WHERE o.district_id = d.id) <> 1;
  -- each council has exactly its expected number of sitting members (place + its districts)
  SELECT count(*) INTO n_size FROM (VALUES
      ('0604982', 'bellflower-council-district-%', 5),
      ('0636546', 'inglewood-council-district-%', 5),
      ('0655156', 'palmdale-council-district-%', 5),
      ('0684200', 'west-covina-council-district-%', 5),
      ('0669088', 'santa-clarita-council-district-%', 5)
    ) AS v(place, pat, size)
   WHERE (SELECT count(DISTINCT och.politician_id) FROM essentials.districts d JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE d.district_type IN ('LOCAL', 'LOCAL_EXEC') AND (d.geo_id = v.place OR d.geo_id LIKE v.pat)
             AND o.title NOT IN ('City Clerk', 'City Treasurer')) = v.size;
  -- NO CROSS-LEAK: an interior point of every district reaches exactly its own district race (if up) or none
  SELECT count(*) INTO n_dleak FROM (
    SELECT a.geo_id, a.up, (SELECT count(*) FROM essentials.races r
        JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
        JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
       WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND r.position_name LIKE '%District%'
         AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(me.geometry))) AS hits
      FROM (VALUES
      ('bellflower-council-district-1', 1),
      ('bellflower-council-district-2', 0),
      ('bellflower-council-district-3', 0),
      ('bellflower-council-district-4', 0),
      ('bellflower-council-district-5', 0),
      ('inglewood-council-district-1', 1),
      ('inglewood-council-district-2', 1),
      ('inglewood-council-district-3', 0),
      ('inglewood-council-district-4', 0),
      ('palmdale-council-district-1', 0),
      ('palmdale-council-district-2', 0),
      ('palmdale-council-district-3', 1),
      ('palmdale-council-district-4', 1),
      ('palmdale-council-district-5', 1),
      ('west-covina-council-district-1', 0),
      ('west-covina-council-district-2', 1),
      ('west-covina-council-district-3', 0),
      ('west-covina-council-district-4', 1),
      ('west-covina-council-district-5', 1),
      ('santa-clarita-council-district-1', 0),
      ('santa-clarita-council-district-2', 1),
      ('santa-clarita-council-district-3', 0),
      ('santa-clarita-council-district-4', 1),
      ('santa-clarita-council-district-5', 1)
      ) AS a(geo_id, up) JOIN essentials.geofence_boundaries me ON me.geo_id = a.geo_id AND me.mtfcc = 'X0001') x
   WHERE x.hits <> x.up;
  IF n_dpoly <> 24 THEN RAISE EXCEPTION 'districts: % of 24 new district rows resolve to a polygon', n_dpoly; END IF;
  IF n_seatok <> 27 THEN RAISE EXCEPTION 'seats: % of 27 seats in place with their named holder', n_seatok; END IF;
  IF n_dbad <> 0 THEN RAISE EXCEPTION '% district row(s) without exactly one office', n_dbad; END IF;
  IF n_size <> 5 THEN RAISE EXCEPTION 'councils: % of 5 at their expected size', n_size; END IF;
  IF n_dleak <> 0 THEN RAISE EXCEPTION '% district(s) reach the wrong number of district races', n_dleak; END IF;
  SELECT count(*) INTO n_wc FROM (VALUES ('1852d689-56bc-4c64-b2d8-ab91a735a470'::uuid, '625a53c8-209f-4231-bbc0-05edbd1c0591'::uuid), ('0e352f7d-7224-4b2c-b4a4-fe74ef17b453'::uuid, 'e4fd3203-bf10-4900-91f0-bf6eb58622a0'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n_wc <> 2 THEN RAISE EXCEPTION 'West Covina: % of 2 clerk/treasurer seats held', n_wc; END IF;
  RAISE NOTICE 'CA_0172 applied: % races, % candidates, % incumbents linked', n_races, n_cands, n_inc;
END $$;

COMMIT;
